  const radial = ctex('k5radial', 64, 64, (g, w, h) => { const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32); gr.addColorStop(0, 'rgba(255,255,255,1)'); gr.addColorStop(0.22, 'rgba(255,255,255,0.55)'); gr.addColorStop(0.55, 'rgba(255,255,255,0.14)'); gr.addColorStop(1, 'rgba(255,255,255,0)'); g.fillStyle = gr; g.fillRect(0, 0, w, h); });
  const addMat = new Map();
  const additive = (key, map, c, op = 1, side) => { const k2 = key + c + op; if (!addMat.has(k2)) addMat.set(k2, new THREE.MeshBasicMaterial({ map, color: c, transparent: true, opacity: op, blending: THREE.AdditiveBlending, depthWrite: false, side: side || THREE.FrontSide })); return addMat.get(k2); };
  const qTmp = new THREE.Quaternion();
