      const cells = [[0, 0, 128, 64], [128, 0, 64, 128], [192, 0, 64, 128], [0, 64, 128, 64], [0, 128, 64, 128], [64, 128, 128, 64], [192, 128, 64, 128], [64, 192, 128, 64]];
