        g.fillStyle = '#3a1418'; if (cw > ch) { g.fillRect(x, y, cw, 5); g.fillRect(x, y + ch - 5, cw, 5); } else { g.fillRect(x, y, 5, ch); g.fillRect(x + cw - 5, y, 5, ch); }
